/**
 * @method
 * @name luno#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://www.luno.com/en/developers/api#tag/Send/operation/ListSupportedNetworks
 * @param {dict} [params] extra parameters specific to the exchange API endpoint
 * @returns {dict} an associative dictionary of currencies
 */
func (this *Luno) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Luno) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if !this.CheckRequiredCredentials(false) {

		ch <- AsyncResult[map[string]any]{Value: map[string]any{}}
		return nil
	}

	r := <-this.PrivateGetSendNetworks(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         "networks": [
	//           {
	//             "id": 0,
	//             "name": "Ethereum",
	//             "native_currency": "ETH"
	//           },
	//           ...
	//         ]
	//     }
	//
	var currenciesData []any = SafeListTyped(response, "data")
	var grouped map[string]any = this.GroupBy(currenciesData, "native_currency")
	var values []any = nil
	if grouped != nil {
		values = make([]any, 0, len(grouped))
		for _, objectValue := range grouped {
			values = append(values, objectValue)
		}
	}

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(values)}
	return nil
}
func (this *Luno) ParseCurrency(rawCurrency any) map[string]any {
	var id *string = this.SafeString(this.SafeDict(rawCurrency, 0), "native_currency") // first item is guaranteed
	var code *string = this.SafeCurrencyCode(id)
	var networks map[string]any = map[string]any{}
	for i := 0; i < GetArrayLength(rawCurrency); i++ {
		var networkEntry map[string]any = SafeMapTyped(rawCurrency, i)
		var networkId *string = this.SafeString(networkEntry, "name")
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		if networkCode != nil {
			networks[*networkCode] = map[string]any{
				"id":      networkId,
				"network": networkCode,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": nil,
						"max": nil,
					},
					"deposit": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
				"active":    nil,
				"deposit":   nil,
				"withdraw":  nil,
				"fee":       nil,
				"precision": nil,
				"info":      networkEntry,
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        id,
		"code":      code,
		"precision": nil,
		"type":      nil,
		"name":      nil,
		"active":    nil,
		"deposit":   nil,
		"withdraw":  nil,
		"fee":       nil,
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": networks,
		"info":     rawCurrency,
	})
}

/**
 * @method
 * @name luno#fetchMarkets
 * @description retrieves data on all markets for luno
 * @see https://www.luno.com/en/developers/api#tag/Market/operation/Markets
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Luno) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Luno) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.ExchangeGetMarkets(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         "markets":[
	//             {
	//                 "market_id":"BCHXBT",
	//                 "trading_status":"ACTIVE",
	//                 "base_currency":"BCH",
	//                 "counter_currency":"XBT",
	//                 "min_volume":"0.01",
	//                 "max_volume":"100.00",
	//                 "volume_scale":2,
	//                 "min_price":"0.0001",
	//                 "max_price":"1.00",
	//                 "price_scale":6,
	//                 "fee_scale":8,
	//             },
	//         ]
	//     }
	//
	var result []any = []any{}
	var markets []any = SafeListTyped(response, "markets")
	for i := 0; i < len(markets); i++ {
		var market any = markets[i]
		var id *string = this.SafeString(market, "market_id")
		var baseId *string = this.SafeString(market, "base_currency")
		var quoteId *string = this.SafeString(market, "counter_currency")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var status *string = this.SafeString(market, "trading_status")
		// Luno's published schedule is categorical, not a single pair. Entry-tier
		// rates below are read from Luno's own Help Centre fee article for the ZAR
		// market; markets quoted in other fiat currencies are left on the
		// exchange-wide default until their schedules are verified the same way.
		var fiats []any = []any{"ZAR"}
		// live-but-unverified counters, kept on the exchange-wide default; the market
		// list is geo-filtered so this is a superset of any one region's view, and
		// ZARU is Luno's tokenized rand ("ZAR Universal"), not fiat, but equally unverified
		var unverifiedQuotes []any = []any{"MYR", "NGN", "IDR", "KES", "UGX", "AUD", "GBP", "EUR", "USD", "ZARU"}
		var stablecoins []any = []any{"USDT", "USDC"}
		var taker *float64 = nil
		var maker *float64 = nil
		if this.InArray(quote, fiats) {
			if this.InArray(base, stablecoins) {
				taker = this.ParseNumber("0.002")
				maker = this.ParseNumber("-0.0001") // a rebate, not a charge
			} else {
				taker = this.ParseNumber("0.006")
				maker = this.ParseNumber("0.004")
			}
		} else if !this.InArray(quote, unverifiedQuotes) {
			// stablecoin-quoted (BTC/USDT) and crypto-quoted (ETH/BTC, SOL/ADA) books
			// are both in Luno's crypto/crypto column
			taker = this.ParseNumber("0.001")
			maker = this.ParseNumber("0.0008")
		}
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         *base + "/" + *quote,
			"taker":          taker,
			"maker":          maker,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         false,
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         (status != nil && *status == "ACTIVE"),
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "volume_scale"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "price_scale"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "min_volume"),
					"max": this.SafeNumber(market, "max_volume"),
				},
				"price": map[string]any{
					"min": this.SafeNumber(market, "min_price"),
					"max": this.SafeNumber(market, "max_price"),
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

