func (this *Luno) ParseOrder(order any, optionalArgs ...any) Order {
	//
	//     {
	//         "base": "string",
	//         "completed_timestamp": "string",
	//         "counter": "string",
	//         "creation_timestamp": "string",
	//         "expiration_timestamp": "string",
	//         "fee_base": "string",
	//         "fee_counter": "string",
	//         "limit_price": "string",
	//         "limit_volume": "string",
	//         "order_id": "string",
	//         "pair": "string",
	//         "state": "PENDING",
	//         "type": "BID"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(order, "creation_timestamp")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "state"))
	var side *string = nil
	var orderType *string = this.SafeString(order, "type")
	if (orderType != nil && *orderType == "ASK") || (orderType != nil && *orderType == "SELL") {
		side = SafeStringPtr("sell")
	} else if (orderType != nil && *orderType == "BID") || (orderType != nil && *orderType == "BUY") {
		side = SafeStringPtr("buy")
	}
	var marketId *string = this.SafeString(order, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var price *string = this.SafeString(order, "limit_price")
	var amount *string = this.SafeString(order, "limit_volume")
	var quoteFee *float64 = this.SafeNumber(order, "fee_counter")
	var baseFee *float64 = this.SafeNumber(order, "fee_base")
	var filled *string = this.SafeString(order, "base")
	var cost *string = this.SafeString(order, "counter")
	var fee map[string]any = nil
	if quoteFee != nil {
		fee = map[string]any{
			"cost":     quoteFee,
			"currency": marketResolved["quote"],
		}
	} else if baseFee != nil {
		fee = map[string]any{
			"cost":     baseFee,
			"currency": marketResolved["base"],
		}
	}
	var id *string = this.SafeString(order, "order_id")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"datetime":           this.Iso8601(timestamp),
		"timestamp":          timestamp,
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             marketResolved["symbol"],
		"type":               nil,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"amount":             amount,
		"filled":             filled,
		"cost":               cost,
		"remaining":          nil,
		"trades":             nil,
		"fee":                fee,
		"info":               order,
		"average":            nil,
	}, marketResolved)
}

