func (this *Luno) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (public)
	//
	//      {
	//          "sequence":276989,
	//          "timestamp":1648651276949,
	//          "price":"35773.20000000",
	//          "volume":"0.00300000",
	//          "is_buy":false
	//      }
	//
	// fetchMyTrades (private)
	//
	//      {
	//          "pair":"LTCXBT",
	//          "sequence":3256813,
	//          "order_id":"BXEX6XHHDT5EGW2",
	//          "type":"ASK",
	//          "timestamp":1648652135235,
	//          "price":"0.002786",
	//          "volume":"0.10",
	//          "base":"0.10",
	//          "counter":"0.0002786",
	//          "fee_base":"0.0001",
	//          "fee_counter":"0.00",
	//          "is_buy":false,
	//          "client_order_id":""
	//      }
	//
	// For public trade data (is_buy === True) indicates 'buy' side but for private trade data
	// is_buy indicates maker or taker. The value of "type" (ASK/BID) indicate sell/buy side.
	// Private trade data includes ID field which public trade data does not.
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var orderId *string = this.SafeString(trade, "order_id")
	var id *string = this.SafeString(trade, "sequence")
	var takerOrMaker *string = nil
	var side *string = nil
	if orderId != nil {
		var typeVar *string = this.SafeString(trade, "type")
		if (typeVar != nil && *typeVar == "ASK") || (typeVar != nil && *typeVar == "SELL") {
			side = SafeStringPtr("sell")
		} else if (typeVar != nil && *typeVar == "BID") || (typeVar != nil && *typeVar == "BUY") {
			side = SafeStringPtr("buy")
		}
		if (side != nil && *side == "sell") && (*this.SafeBool(trade, "is_buy", false)) {
			takerOrMaker = SafeStringPtr("maker")
		} else if (side != nil && *side == "buy") && (!(*this.SafeBool(trade, "is_buy", false))) {
			takerOrMaker = SafeStringPtr("maker")
		} else {
			takerOrMaker = SafeStringPtr("taker")
		}
	} else {
		side = SafeStringPtr(func() string {
			if *this.SafeBool(trade, "is_buy", false) {
				return "buy"
			}
			return "sell"
		}())
	}
	var feeBaseString *string = this.SafeString(trade, "fee_base")
	var feeCounterString *string = this.SafeString(trade, "fee_counter")
	var feeCurrency *string = nil
	var feeCost *string = nil
	if feeBaseString != nil {
		if !Precise.StringEquals(feeBaseString, "0.0") {
			feeCurrency = this.SafeString(market, "base")
			feeCost = feeBaseString
		}
	} else if feeCounterString != nil {
		if !Precise.StringEquals(feeCounterString, "0.0") {
			feeCurrency = this.SafeString(market, "quote")
			feeCost = feeCounterString
		}
	}
	var timestamp *int64 = this.SafeInteger(trade, "timestamp")
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       this.SafeString(market, "symbol"),
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString2(trade, "volume", "base"),
		"cost":         this.SafeString(trade, "counter"),
		"fee": map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		},
	}, market)
}

