/**
 * @method
 * @name luno#fetchOHLCV
 * @see https://www.luno.com/en/developers/api#tag/Market/operation/GetCandles
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Luno) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Luno) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"duration": this.SafeValue(this.Timeframes, timeframe, timeframe),
		"pair":     market["id"],
	}
	if since != nil {
		request["since"] = this.ParseToInt(since)
	} else {
		var duration int64 = (1000 * 1000) * this.ParseTimeframe(timeframe)
		request["since"] = this.Milliseconds() - duration
	}

	r1 := <-this.ExchangePrivateGetCandles(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//          "candles": [
	//              {
	//                  "timestamp": 1664055240000,
	//                  "open": "19612.65",
	//                  "close": "19612.65",
	//                  "high": "19612.65",
	//                  "low": "19612.65",
	//                  "volume": "0.00"
	//              },...
	//          ],
	//          "duration": 60,
	//          "pair": "XBTEUR"
	//     }
	//
	var ohlcvs []any = SafeListTypedDefault(response, "candles", []any{})

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(ohlcvs, market, timeframe, since, limit))}
	return nil
}
func (this *Luno) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	// {
	//     "timestamp": 1664055240000,
	//     "open": "19612.65",
	//     "close": "19612.65",
	//     "high": "19612.65",
	//     "low": "19612.65",
	//     "volume": "0.00"
	// }
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return OHLCVFromList([]any{this.SafeInteger(ohlcv, "timestamp"), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume")})
}

