/**
 * @method
 * @name luno#createOrder
 * @description create a trade order
 * @see https://www.luno.com/en/developers/api#tag/Orders/operation/PostMarketOrder
 * @see https://www.luno.com/en/developers/api#tag/Orders/operation/PostLimitOrder
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Luno) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Luno) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}
	var response map[string]any = nil
	this.CheckRequiredArgument("createOrder", side, "side")
	if typeVar == "market" {
		request["type"] = strings.ToUpper(side)
		// todo add createMarketBuyOrderRequires price logic as it is implemented in the other exchanges
		if side == "buy" {
			request["counter_volume"] = this.AmountToPrecision(market["symbol"], amount)
		} else {
			request["base_volume"] = this.AmountToPrecision(market["symbol"], amount)
		}

		r1 := <-this.PrivatePostMarketorder(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {
		request["volume"] = this.AmountToPrecision(market["symbol"], amount)
		request["price"] = this.PriceToPrecision(market["symbol"], price)
		request["type"] = func() string {
			if side == "buy" {
				return "BID"
			}
			return "ASK"
		}()

		r2 := <-this.PrivatePostPostorder(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}
	if response == nil {
		panic(NullResponse(this.Id + " createOrder() returned empty response"))
	}
	var orderId *string = this.SafeString(response, "order_id")

	ch <- AsyncResult[Order]{Value: this.SafeOrder(map[string]any{
		"info": response,
		"id":   orderId,
	}, market)}
	return nil
}

