func (this *Luno) FetchLedgerByEntriesAsync(optionalArgs ...any) <-chan AsyncResult[[]LedgerEntry] {
	ch := make(chan AsyncResult[[]LedgerEntry], 1)
	go this.fetchLedgerByEntriesBody(ch, optionalArgs...)
	return ch
}
func (this *Luno) fetchLedgerByEntriesBody(ch chan AsyncResult[[]LedgerEntry], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// by default without entry number or limit number, return most recent entry
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	entry := GetArg(optionalArgs, 1, nil)
	_ = entry
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var entryValue any = func() any {
		if entry == nil {
			return int64(-1)
		}
		return entry
	}()
	var limitValue int64 = func() int64 {
		if limit == nil {
			return 1
		}
		return *limit
	}()
	var since any = nil
	var request map[string]any = map[string]any{
		"min_row": entryValue,
		"max_row": this.Sum(entryValue, limitValue),
	}

	r := <-this.FetchLedgerAsync(code, since, limitValue, this.Extend(request, params))
	if r.Err != nil {
		panic(r.Err)
	}
	var retRes141115 []any = LedgerEntriesToList(r.Value)
	if retRes141115 == nil {
		ch <- AsyncResult[[]LedgerEntry]{Value: nil}
	} else {
		ch <- AsyncResult[[]LedgerEntry]{Value: LedgerEntriesFromList(retRes141115)}
	}
	return nil
}

/**
 * @method
 * @name luno#fetchLedger
 * @description fetch the history of changes, actions done by the user or operations that altered the balance of the user
 * @see https://www.luno.com/en/developers/api#tag/Accounts/operation/ListTransactions
 * @param {string} [code] unified currency code, default is undefined
 * @param {int} [since] timestamp in ms of the earliest ledger entry, default is undefined
 * @param {int} [limit] max number of ledger entries to return, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
 */
func (this *Luno) FetchLedgerAsync(optionalArgs ...any) <-chan AsyncResult[[]LedgerEntry] {
	ch := make(chan AsyncResult[[]LedgerEntry], 1)
	go this.fetchLedgerBody(ch, optionalArgs...)
	return ch
}
func (this *Luno) fetchLedgerBody(ch chan AsyncResult[[]LedgerEntry], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.LoadAccountsAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var currency map[string]any = nil
	var id *string = this.SafeString(params, "id") // account id
	var minRowParam *int64 = this.SafeInteger(params, "min_row")
	var maxRowParam *int64 = this.SafeInteger(params, "max_row")
	if id == nil {
		if code == nil {
			panic(ArgumentsRequired(this.Id + " fetchLedger() requires a currency code argument if no account id specified in params"))
		}
		currency = this.Currency(code)
		var accountsByCurrencyCode map[string]any = this.IndexBy(this.Accounts, "currency")
		var account map[string]any = SafeMapTyped(accountsByCurrencyCode, code)
		if account == nil {
			panic(ExchangeError(this.Id + " fetchLedger() could not find account id for " + *code))
		}
		id = this.SafeString(account, "id")
	}
	if ((minRowParam == nil) || (maxRowParam == nil)) && ((minRowParam != nil) || (maxRowParam != nil)) {
		panic(ExchangeError(this.Id + " fetchLedger() require both params 'max_row' and 'min_row' or neither to be defined"))
	}
	var maxRowBase *int64 = this.SafeInteger(params, "max_row", 0)            // Default to most recent transactions
	var minRowBase *int64 = this.SafeInteger(params, "min_row", int64(-1000)) // Maximum number of records supported
	var limitApplies bool = (limit != nil) && (*maxRowBase-*minRowBase > *limit)
	var min_row *int64 = func() *int64 {
		if limitApplies && (limit != nil) && (maxRowBase == nil || *maxRowBase <= 0) {
			return Int64PtrTyped(*maxRowBase - *limit)
		}
		return minRowBase
	}()
	var max_row any = maxRowBase
	if limitApplies && (maxRowBase != nil && *maxRowBase > 0) && (minRowBase != nil && *minRowBase > 0) {
		max_row = *minRowBase + *limit
	}
	var limitAdjusts bool = limitApplies && ((maxRowBase == nil || *maxRowBase <= 0) || (minRowBase != nil && *minRowBase > 0)) // max_row - min_row becomes limit
	if (limitAdjusts && (limit != nil && *limit > 1000)) || (!limitAdjusts && (*maxRowBase-*minRowBase > 1000)) {
		panic(ExchangeError(this.Id + " fetchLedger() requires the params 'max_row' - 'min_row' <= 1000"))
	}
	var request map[string]any = map[string]any{
		"id":      id,
		"min_row": min_row,
		"max_row": max_row,
	}

	r2 := <-this.PrivateGetAccountsIdTransactions(this.Extend(params, request))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	var entries []any = SafeListTypedDefault(response, "transactions", []any{})

	ch <- AsyncResult[[]LedgerEntry]{Value: LedgerEntriesFromList(this.ParseLedger(entries, currency, since, limit))}
	return nil
}
func (this *Luno) ParseLedgerComment(comment *string) map[string]any {
	var words []string = strings.Split(*comment, " ")
	var types map[string]any = map[string]any{
		"Withdrawal": "fee",
		"Trading":    "fee",
		"Payment":    "transaction",
		"Sent":       "transaction",
		"Deposit":    "transaction",
		"Received":   "transaction",
		"Released":   "released",
		"Reserved":   "reserved",
		"Sold":       "trade",
		"Bought":     "trade",
		"Failure":    "failed",
	}
	var referenceId *string = nil
	var firstWord *string = this.SafeString(words, 0)
	var thirdWord *string = this.SafeString(words, 2)
	var fourthWord *string = this.SafeString(words, 3)
	var typeVar *string = this.SafeString(types, firstWord)
	if (typeVar == nil) && (thirdWord != nil && *thirdWord == "fee") {
		typeVar = SafeStringPtr("fee")
	}
	if (typeVar != nil && *typeVar == "reserved") && (fourthWord != nil && *fourthWord == "order") {
		referenceId = this.SafeString(words, 4)
	}
	return map[string]any{
		"type":        typeVar,
		"referenceId": referenceId,
	}
}
func (this *Luno) ParseLedgerEntry(entry any, optionalArgs ...any) LedgerEntry {
	// const details = this.safeValue (entry, 'details', {});
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(entry, "row_index")
	var account_id *string = this.SafeString(entry, "account_id")
	var timestamp *int64 = this.SafeInteger(entry, "timestamp")
	var currencyId *string = this.SafeString(entry, "currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var currencyResolved map[string]any = this.SafeCurrency(currencyId, currency)
	var available_delta *string = this.SafeString(entry, "available_delta")
	var balance_delta *string = this.SafeString(entry, "balance_delta")
	var after *string = this.SafeString(entry, "balance")
	var comment *string = this.SafeString(entry, "description", "")
	var before *string = after
	var amount any = "0.0"
	var result map[string]any = this.ParseLedgerComment(comment)
	var resultType *string = this.SafeString(result, "type")
	var resultReferenceId *string = this.SafeString(result, "referenceId")
	var direction *string = nil
	var status *string = nil
	if !Precise.StringEquals(balance_delta, "0.0") {
		before = Precise.StringSub(after, balance_delta)
		status = SafeStringPtr("ok")
		amount = Precise.StringAbs(balance_delta)
	} else if Precise.StringLt(available_delta, "0.0") {
		status = SafeStringPtr("pending")
		amount = Precise.StringAbs(available_delta)
	} else if Precise.StringGt(available_delta, "0.0") {
		status = SafeStringPtr("canceled")
		amount = Precise.StringAbs(available_delta)
	}
	if Precise.StringGt(balance_delta, "0") || Precise.StringGt(available_delta, "0") {
		direction = SafeStringPtr("in")
	} else if Precise.StringLt(balance_delta, "0") || Precise.StringLt(available_delta, "0") {
		direction = SafeStringPtr("out")
	}
	return this.SafeLedgerEntry(map[string]any{
		"info":             entry,
		"id":               id,
		"direction":        direction,
		"account":          account_id,
		"referenceId":      resultReferenceId,
		"referenceAccount": nil,
		"type":             resultType,
		"currency":         code,
		"amount":           this.ParseToNumeric(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           this.ParseToNumeric(before),
		"after":            this.ParseToNumeric(after),
		"status":           status,
		"fee":              nil,
	}, currencyResolved)
}

